async function auth(mode){
  el.innerHTML=`<section class="public-shell"><div class="auth-card"><div class="brand">${brandLogo()}<div><strong>${esc(appState.club_name||"Cyber Club")}</strong><small>Espace réservé aux membres</small></div></div><div class="tabs"><button id="tl" class="tab ${mode==="login"?"active":""}">Connexion</button><button id="tr" class="tab ${mode==="register"?"active":""}">Inscription</button></div><div id="ab"></div><button class="btn ghost wide mt" id="homeB">← Retour à l'accueil</button></div></section>`;
  const tl=document.getElementById("tl"),tr=document.getElementById("tr"),ab=document.getElementById("ab"),homeB=document.getElementById("homeB");
  tl.onclick=()=>auth("login");tr.onclick=()=>auth("register");homeB.onclick=landing;
  if(mode==="login"){
    ab.innerHTML=`<form id="lf" class="form"><label>Adresse e-mail</label><input name="email" type="email" autocomplete="email" maxlength="254" required><label>Mot de passe</label><input name="password" type="password" autocomplete="current-password" required><button class="btn primary">Se connecter</button><button type="button" class="btn ghost" id="forgotB">Mot de passe oublié ?</button></form>`;
    const lf=document.getElementById("lf"),forgotB=document.getElementById("forgotB");
    lf.onsubmit=async e=>{e.preventDefault();let btn=e.submitter||e.target.querySelector('button[type="submit"]'),f=new FormData(e.target);if(btn){btn.disabled=true;btn.textContent="Connexion…"}try{let {data,error}=await sb.auth.signInWithPassword({email:f.get("email").trim(),password:f.get("password")});if(error)return toast("❌ "+errFr(error));sess=data.session;if(!sess)return toast("❌ Session de connexion introuvable.");await boot()}catch(err){console.error("Erreur de connexion",err);toast("❌ "+errFr(err))}finally{if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent="Se connecter"}}};
    forgotB.onclick=forgotPassword;
    return;
  }

  let inv=currentInvite();
  const manualGate=(message="")=>{
    ab.innerHTML=`<div class="invite-gate"><div class="invite-icon">▦</div><h2>Inscription sur invitation individuelle</h2>${message?`<div class="warning-box"><strong>⚠ ${esc(message)}</strong></div>`:""}<p>Chaque futur membre reçoit son propre <strong>QR code à usage unique</strong>. Scanne le QR envoyé par l’administrateur pour ouvrir directement ton inscription.</p><div class="notice"><strong>🔐 Sécurité</strong><p>Chaque QR est unique, expire automatiquement et devient définitivement inutilisable dès qu’un compte est créé avec lui.</p></div><button class="btn secondary wide" id="manualInvite">Saisir le code de secours</button><div id="manualBox" class="form mt" hidden><label>Code d'invitation individuel</label><input id="manualCode" maxlength="5" minlength="5" pattern="[A-Za-z2-9]{5}" autocomplete="off" placeholder="ABCDE" style="text-transform:uppercase" required><button class="btn primary" id="useManual" type="button">Utiliser ce code</button></div></div>`;
    const manualInvite=document.getElementById("manualInvite"),manualBox=document.getElementById("manualBox"),manualCode=document.getElementById("manualCode"),useManual=document.getElementById("useManual");
    manualInvite.onclick=()=>{manualBox.hidden=!manualBox.hidden;if(!manualBox.hidden)manualCode.focus()};
    useManual.onclick=()=>{let code=manualCode.value.trim().toUpperCase();if(!/^[A-Z2-9]{5}$/.test(code))return toast("❌ Le code doit contenir exactement 5 caractères.");sessionStorage.setItem("invite",code);history.replaceState({},"",inviteLink(code));auth("register")};manualCode.oninput=()=>{manualCode.value=manualCode.value.toUpperCase().replace(/[^A-Z2-9]/g,"").slice(0,5)};
  };

  if(!inv){manualGate();return}
  ab.innerHTML=`<div class="boot" style="min-height:180px">Vérification de l’invitation…</div>`;
  let {data:check,error:checkError}=await sb.rpc("check_invitation",{p_invite:inv});
  if(checkError||!check?.valid){manualGate(checkError?errFr(checkError):inviteReasonLabel(check?.reason));return}

  sessionStorage.setItem("invite",inv);
  ab.innerHTML=`<div class="invite-ok"><span>✅</span><div><strong>Invitation valide</strong><small>Usage unique • expire le ${esc(fmt(check.expires_at))}</small></div></div><form id="rf" class="form mt"><input name="invite" type="hidden" value="${esc(inv)}"><label>Code d'invitation transmis par le QR</label><input value="${esc(inv)}" readonly aria-readonly="true" style="text-transform:uppercase;font-weight:700;letter-spacing:.18em"><small class="muted">Le code a été rempli automatiquement par le QR. Tu n'as rien à saisir.</small><div class="two"><div><label>Nom complet</label><input name="name" maxlength="80" required></div><div><label>Pseudo</label><input name="username" minlength="3" maxlength="30" pattern="[A-Za-z0-9_.-]+" required></div></div><label>Adresse e-mail</label><input name="email" type="email" maxlength="254" autocomplete="email" required><small class="muted">Cette adresse servira à confirmer ton compte et à te connecter.</small><div class="two"><div><label>Université / établissement</label><input name="university" maxlength="100" required></div><div><label>Niveau d'étude</label><input name="study_level" maxlength="50" placeholder="Ex. L2" required></div></div><div class="two"><div><label>Mot de passe</label><input name="password" type="password" minlength="12" autocomplete="new-password" placeholder="12 caractères minimum" required></div><div><label>Confirmation</label><input name="password2" type="password" minlength="12" autocomplete="new-password" placeholder="Retaper le mot de passe" required></div></div><small class="muted">Utilise une phrase de passe unique d'au moins 12 caractères.</small><button class="btn primary">Terminer mon inscription</button></form>`;
  document.getElementById("rf").onsubmit=register;
}
function forgotPassword(){
  ab.innerHTML=`<form id="fp" class="form"><h3>Réinitialiser le mot de passe</h3><p class="muted">Entre l'adresse e-mail de ton compte. Un lien sécurisé te sera envoyé.</p><input name="email" type="email" maxlength="254" autocomplete="email" required><button class="btn primary">Envoyer le lien</button><button type="button" class="btn ghost" id="backLogin">Retour</button></form>`;
  backLogin.onclick=()=>auth("login");
  fp.onsubmit=async e=>{e.preventDefault();let email=new FormData(e.target).get("email").trim();let {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:appBaseUrl()});if(error)return toast("❌ "+errFr(error));fp.innerHTML=`<div class="notice"><h3>📧 E-mail envoyé</h3><p>Si ce compte existe, un lien de réinitialisation a été envoyé à cette adresse.</p></div>`};
}
function recoveryScreen(){
  el.innerHTML=`<section class="public-shell"><div class="auth-card"><div class="brand">${brandLogo()}<div><strong>${esc(appState.club_name||"Cyber Club")}</strong><small>Réinitialisation sécurisée</small></div></div><form id="recoveryForm" class="form mt"><h2>Nouveau mot de passe</h2><input name="p" type="password" minlength="12" autocomplete="new-password" placeholder="12 caractères minimum" required><input name="p2" type="password" minlength="12" autocomplete="new-password" placeholder="Confirmer" required><button class="btn primary">Enregistrer</button></form></div></section>`;
  recoveryForm.onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),p=f.get("p");if(p!==f.get("p2"))return toast("❌ Confirmation différente");let {error}=await sb.auth.updateUser({password:p});if(error)return toast("❌ "+errFr(error));toast("✅ Mot de passe modifié");await sb.auth.signOut();history.replaceState({},"",appBaseUrl());auth("login")};
}
async function register(e){
  e.preventDefault();let f=new FormData(e.target),p=f.get("password"),invite=f.get("invite").trim().toUpperCase(),email=f.get("email").trim().toLowerCase(),btn=e.submitter||e.target.querySelector('button[type="submit"]');
  if(p!==f.get("password2"))return toast("❌ Mots de passe différents.");
  if(String(p).length<12)return toast("❌ Utilise au moins 12 caractères.");
  if(btn){btn.disabled=true;btn.textContent="Vérification…"}
  try{
    let {data:check,error:checkError}=await sb.rpc("check_invitation",{p_invite:invite});
    if(checkError)return toast("❌ "+errFr(checkError));
    if(!check?.valid)return toast("❌ "+inviteReasonLabel(check?.reason));
    sessionStorage.setItem("invite",invite);
    if(btn)btn.textContent="Création du compte…";
    let {data,error}=await sb.auth.signUp({email,password:p,options:{emailRedirectTo:inviteLink(invite),data:{name:f.get("name").trim(),username:f.get("username").trim(),university:f.get("university").trim(),study_level:f.get("study_level").trim(),invite}}});
    if(error)return toast("❌ "+errFr(error));
    sessionStorage.removeItem("invite");
    history.replaceState({},"",appBaseUrl());
    if(data.session){sess=data.session;await boot()}
    else ab.innerHTML=`<div class="notice"><h3>📧 Inscription terminée</h3><p>Un e-mail de confirmation vient de t’être envoyé. Confirme ton adresse e-mail, puis patiente : ton compte restera en attente jusqu’à l’acceptation par l’administrateur.</p><p class="muted">Cette invitation a été consommée lors de la création du compte : le QR code et son code ne peuvent plus être réutilisés.</p></div>`;
  }catch(err){console.error("Erreur inscription",err);toast("❌ "+errFr(err))}
  finally{if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent="Terminer mon inscription"}}
}
async function applyInvite(){let i=currentInvite();if(!i)return false;let {error}=await sb.rpc("apply_membership",{p_invite:i});if(error){toast("❌ "+errFr(error));return false}sessionStorage.removeItem("invite");if(inviteFromUrl())history.replaceState({},"",appBaseUrl());return true}
async function boot(){
  if(!sess)return landing();
  let {data,error}=await sb.from("profiles").select("*").eq("id",sess.user.id).single();
  if(error)return toast("Profil introuvable.");
  me=data;
  // L'invitation est normalement consommée par le trigger au moment de la création du compte.
  // On ne tente apply_membership que pour un ancien compte qui n'est pas encore vérifié.
  if(!me.invite_verified&&currentInvite()){
    let applied=await applyInvite();
    if(applied){let r=await sb.from("profiles").select("*").eq("id",sess.user.id).single();if(!r.error&&r.data)me=r.data}
  }else if(me.invite_verified){
    sessionStorage.removeItem("invite");
    if(inviteFromUrl())history.replaceState({},"",appBaseUrl());
  }
  sb.rpc("touch_last_seen");
  if(appState.maintenance&&me.role!=="admin")return maintenanceScreen();
  if(!me.invite_verified)return inviteScreen();
  if(me.status!=="ACTIVE")return waiting();
  shell();go(page);
}
function maintenanceScreen(){el.innerHTML=`<section class="public-shell"><div class="auth-card"><div class="warning-box"><h2>🛠 Maintenance</h2><p>La plateforme est temporairement fermée par l'administrateur.</p></div><button class="btn ghost wide mt" id="lo">Déconnexion</button></div></section>`;lo.onclick=()=>sb.auth.signOut()}
function inviteScreen(){el.innerHTML=`<section class="public-shell"><div class="auth-card"><div class="warning-box"><h2>Invitation requise</h2><p>Ton compte n'a pas encore reçu d'invitation valide. Rouvre le lien obtenu en scannant le QR code ou saisis le code manuellement ci-dessous.</p></div><form id="iv" class="form mt"><label>Code d'invitation</label><input name="code" maxlength="128" required><button class="btn primary">Valider l'invitation</button></form><button class="btn ghost wide mt" id="lo">Déconnexion</button></div></section>`;iv.onsubmit=async e=>{e.preventDefault();let {error}=await sb.rpc("apply_membership",{p_invite:new FormData(e.target).get("code")});if(error)toast("❌ "+errFr(error));else boot()};lo.onclick=()=>sb.auth.signOut()}
function waiting(){
  el.innerHTML=`<section class="public-shell"><div class="auth-card"><div class="warning-box"><h2>${me.status==="PENDING"?"✅ Inscription terminée":"Compte "+esc(statusLabel(me.status))}</h2><p>${me.status==="PENDING"?"Ton adresse e-mail est validée. Patiente maintenant pendant que l'administrateur accepte ton compte.":"Ton accès n'est pas actif."}</p></div><div class="actions mt"><button class="btn secondary" id="rfsh">Actualiser</button><button class="btn ghost" id="lo">Déconnexion</button></div></div></section>`;
  rfsh.onclick=boot;lo.onclick=()=>sb.auth.signOut();
}
function shell(){
  let sup=["trainer","organizer","admin"].includes(me.role),tr=["trainer","admin"].includes(me.role),org=["organizer","admin"].includes(me.role);
  el.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">${brandLogo()}<div><strong>${esc(appState.club_name||"Cyber Club")}</strong><small>${esc(appState.club_tagline||"Plateforme de cybersécurité")}</small></div></div><nav>${nav("dashboard","◈ Tableau de bord")}${nav("courses","▤ Cours")}${nav("training","⚑ Entraînement")}${nav("teams","👥 Équipes")}${nav("ctf","🚩 CTF hebdomadaire")}${nav("archives","🗂 Archives CTF")}${nav("calendar","📅 Calendrier")}${nav("leaderboard","🏆 Classements")}${nav("writeups","📝 Write-ups")}${nav("announcements","📢 Annonces")}${nav("notifications","🔔 Notifications")}${nav("statistics","📊 Statistiques")}${nav("profile","👤 Profil")}${appState.ai_enabled||me.role==="admin"?nav("assistant","🤖 Assistant IA"):""}${sup?nav("supervision","👁 Suivi des membres"):""}${sup?nav("live","📡 CTF en direct"):""}${tr?nav("trainer","🧑‍🏫 Formateur"):""}${org?nav("organizer","🏁 Organisation CTF"):""}${me.role==="admin"?nav("admin","⚙ Administration"):""}</nav><div class="sidebar-bottom"><div class="userbox"><strong>@${esc(me.username)}</strong><small>${esc(me.email)}</small><span class="badge ${rb(me.role)}">${roles[me.role]}</span></div><button class="btn ghost wide" id="logout">Déconnexion</button></div></aside><main class="main"><header class="topbar"><div class="topbar-left"><button id="menu" class="menu-btn">☰</button><strong id="pt">${esc(routeLabels[page]||appState.club_name||"Cyber Club")}</strong></div><span class="badge cyan">⭐ ${me.xp} XP • Niveau ${me.level}</span></header><div id="content" class="content"></div></main></div>`;
  document.querySelectorAll("[data-r]").forEach(b=>b.onclick=()=>go(b.dataset.r));logout.onclick=()=>sb.auth.signOut();menu.onclick=()=>document.querySelector(".sidebar").classList.toggle("open");mountCyberBot();refreshUnreadCount();if(notificationPoll)clearInterval(notificationPoll);notificationPoll=setInterval(refreshUnreadCount,45000);
}
async function go(r){page=r;setCyberBotContext({page:r});document.querySelectorAll(".nav-btn").forEach(b=>b.classList.toggle("active",b.dataset.r===r));document.querySelector(".sidebar")?.classList.remove("open");let c=document.getElementById("content");c.innerHTML=`<div class="boot" style="min-height:280px">Chargement…</div>`;let map={dashboard:dashboard,courses:courses,training:training,teams:teams,ctf:ctf,archives:archives,calendar:calendar,leaderboard:leaderboard,writeups:writeups,announcements:announcements,notifications:notifications,statistics:statistics,profile:profile,assistant:assistant,supervision:supervision,live:live,trainer:trainer,organizer:organizer,admin:admin};pt.textContent=routeLabels[r]||r;try{await (map[r]||dashboard)(c)}catch(e){console.error(e);c.innerHTML=`<div class="card"><h2>Erreur</h2><p>${esc(errFr(e))}</p></div>`}}
async function refreshMe(){let {data}=await sb.from("profiles").select("*").eq("id",me.id).single();if(data)me=data}

async function dashboard(c){
  const now=new Date(),future=new Date(now.getTime()+90*24*60*60*1000);
  let [{data:p},{data:s},{data:a},{data:e},{data:t},{data:cal}]=await Promise.all([
    sb.from("lesson_progress").select("lesson_id").eq("user_id",me.id),
    sb.from("solves").select("points,event_id").eq("user_id",me.id),
    sb.from("announcements").select("*").order("pinned",{ascending:false}).order("created_at",{ascending:false}).limit(3),
    sb.from("ctf_events").select("*").eq("is_open",true).limit(1),
    sb.rpc("get_my_team"),
    sb.rpc("get_calendar_events",{p_from:now.toISOString(),p_to:future.toISOString()})
  ]);
  let active=e?.[0],score=(s||[]).filter(x=>!x.event_id).reduce((x,y)=>x+y.points,0);
  let upcoming=(cal||[]).filter(x=>new Date(x.ends_at||x.starts_at).getTime()>Date.now()).sort((x,y)=>new Date(x.starts_at)-new Date(y.starts_at))[0];
  const nextCard=upcoming?`<div class="card countdown-card"><div class="between"><div><span class="badge cyan">${esc(calendarTypeLabel(upcoming.event_type))}</span><h2>${esc(upcoming.title)}</h2><p>${esc(upcoming.description||"")}</p><small class="muted">${fmt(upcoming.starts_at)}${upcoming.location?` • ${esc(upcoming.location)}`:""}</small></div><div class="countdown-big" data-countdown data-start="${esc(upcoming.starts_at)}" data-end="${esc(upcoming.ends_at||"")}"></div></div><button class="btn secondary mt" id="dashCalendar">Voir le calendrier</button></div>`:`<div class="card"><h2>Prochain événement</h2><p>Aucun événement programmé pour les 90 prochains jours.</p><button class="btn secondary" id="dashCalendar">Voir le calendrier</button></div>`;
  c.innerHTML=`<section class="hero"><span class="badge purple">Bonjour @${esc(me.username)}</span><h1>Prêt à progresser ?</h1><p>Cours, défis, équipes et CTF du club.</p></section><div class="grid cols4">${stat("📚","Leçons",p?.length||0)}${stat("🚩","Résolutions",s?.length||0)}${stat("⭐","Entraînement",score)}${stat("👥","Équipe",t?.team?.name||"Aucune")}</div><div class="mt">${nextCard}</div><div class="grid cols2 mt"><div class="card"><h2>CTF hebdomadaire</h2>${active?`<span class="badge green">OUVERT</span><h3>${esc(active.title)}</h3><button class="btn primary" data-open-event="${active.id}">Voir</button>`:"<p>Aucun CTF ouvert.</p>"}</div><div class="card"><h2>Annonces</h2>${(a||[]).map(x=>`<div class="mini-item"><strong>${x.pinned?"📌 ":""}${esc(x.title)}</strong><p>${esc(x.body)}</p></div>`).join("")||empty("Aucune annonce.")}</div></div>`;
  c.querySelectorAll("[data-open-event]").forEach(b=>b.onclick=()=>openEvent(b.dataset.openEvent));
  c.querySelector("#dashCalendar").onclick=()=>go("calendar");
  bindCountdowns(c);
}
async function courses(c){let [{data:co},{data:l},{data:p}]=await Promise.all([sb.from("courses").select("*").eq("published",true).order("created_at"),sb.from("lessons").select("id,course_id"),sb.from("lesson_progress").select("lesson_id").eq("user_id",me.id)]);cache.courses=co||[];let d=new Set((p||[]).map(x=>x.lesson_id));c.innerHTML=`<section class="hero"><h1>📚 Cours</h1></section><div class="grid cols3">${(co||[]).map(x=>{let ls=(l||[]).filter(z=>z.course_id===x.id),n=ls.filter(z=>d.has(z.id)).length;return `<div class="card course-card"><div class="course-icon">${esc(x.icon)}</div><h3>${esc(x.title)}</h3><span class="badge">${esc(x.level)}</span><p>${n}/${ls.length} leçons</p><div class="progress"><span style="width:${ls.length?n*100/ls.length:0}%"></span></div><button class="btn secondary" data-course="${x.id}">Ouvrir</button></div>`}).join("")}</div>`;c.querySelectorAll("[data-course]").forEach(b=>b.onclick=()=>openCourse(b.dataset.course))}
async function openCourse(id,focusLessonId=null){
  let c=document.getElementById("content"),[{data:co},{data:l},{data:p},{data:q}]=await Promise.all([sb.from("courses").select("*").eq("id",id).single(),sb.from("lessons").select("*").eq("course_id",id).order("position"),sb.from("lesson_progress").select("lesson_id").eq("user_id",me.id),sb.from("quizzes").select("*").eq("course_id",id).maybeSingle()]);
  let d=new Set((p||[]).map(x=>x.lesson_id));setCyberBotContext({page:"course",course:{id:co.id,title:co.title}});
  c.innerHTML=`<button class="btn ghost" id="back">← Retour</button><section class="hero mt"><h1>${esc(co.icon)} ${esc(co.title)}</h1><p>${esc(co.description||"")}</p>${appState.ai_enabled?`<button class="btn secondary" id="askAiCourse">🤖 Demander à CyberBot sur ce cours</button>`:""}</section><div class="card">${(l||[]).map(x=>`<div class="lesson between" data-lesson-id="${x.id}"><div><strong>${esc(x.title)}</strong><p>${esc(x.content||"")}</p>${appState.ai_enabled?`<button class="btn ghost ai-lesson-btn" data-ai-lesson="${x.id}">🤖 Expliquer cette leçon</button>`:""}</div><button class="btn ${d.has(x.id)?"success":"secondary"}" data-l="${x.id}">${d.has(x.id)?"✅":"Valider"}</button></div>`).join("")}</div><div id="quiz" class="mt"></div>`;
  back.onclick=()=>go("courses");
  let cab=c.querySelector("#askAiCourse");if(cab)cab.onclick=()=>showAiModal({page:"course",course:{id:co.id,title:co.title}});
  c.querySelectorAll("[data-ai-lesson]").forEach(b=>b.onclick=()=>{let x=(l||[]).find(z=>z.id===b.dataset.aiLesson);if(x)showAiModal({page:"course",course:{id:co.id,title:co.title},lesson:{id:x.id,title:x.title}})});
  c.querySelectorAll("[data-l]").forEach(b=>b.onclick=async()=>{let {data,error}=await sb.rpc("mark_lesson_complete",{p_lesson:b.dataset.l});if(error)toast("❌ "+errFr(error));else{toast(data.new?`✅ +${data.xp} XP`:"Déjà fait");await refreshMe();openCourse(id,b.dataset.l)}});
  if(q)renderQuiz(document.getElementById("quiz"),q);
  if(focusLessonId)setTimeout(()=>{let n=c.querySelector(`[data-lesson-id="${CSS.escape(String(focusLessonId))}"]`);if(n){n.scrollIntoView({behavior:"smooth",block:"center"});n.style.outline="2px solid rgba(103,217,255,.65)";setTimeout(()=>n.style.outline="",2200)}},120);
}
async function renderQuiz(e,q){let [{data:qs},{data:r}]=await Promise.all([sb.from("quiz_questions").select("*").eq("quiz_id",q.id).order("position"),sb.from("quiz_results").select("*").eq("quiz_id",q.id).eq("user_id",me.id).maybeSingle()]);e.innerHTML=`<div class="card"><h2>${esc(q.title)}</h2>${r?`<p>${r.score}/${r.total} — ${r.passed?"✅ Réussi":"À refaire"}</p>`:""}<form id="qf" class="form">${(qs||[]).map((x,i)=>`<div class="panel"><strong>${i+1}. ${esc(x.question)}</strong>${(x.options||[]).map((o,j)=>`<label><input class="inlinecheck" type="radio" name="q${i}" value="${j}" required> ${esc(o)}</label>`).join("")}</div>`).join("")}<button class="btn primary">Envoyer</button></form></div>`;qf.onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),ans=(qs||[]).map((_,i)=>Number(f.get(`q${i}`))),{data,error}=await sb.rpc("submit_quiz",{p_quiz:q.id,p_answers:ans});if(error)toast("❌ "+errFr(error));else{toast(`${data.passed?"✅":"⚠️"} ${data.score}/${data.total}`);renderQuiz(e,q)}}}

async function challengeList(eventId=null){let {data:ch}=await sb.from("challenges").select("*").eq("published",true).order("base_points");if(!eventId)ch=(ch||[]).filter(x=>x.training_enabled);else{let {data:l}=await sb.from("ctf_event_challenges").select("challenge_id").eq("event_id",eventId),set=new Set((l||[]).map(x=>x.challenge_id));ch=(ch||[]).filter(x=>set.has(x.id))}let {data:s}=await sb.from("solves").select("challenge_id,event_id").eq("user_id",me.id);return (ch||[]).map(x=>({...x,solved:(s||[]).some(z=>z.challenge_id===x.id&&(eventId?z.event_id===eventId:!z.event_id))}))}
const filt=()=>`<div class="filterbar"><input id="search" placeholder="🔎 Rechercher"><select id="cat"><option value="">Toutes les catégories</option>${Object.keys(categoryLabels).map(x=>`<option value="${x}">${categoryLabel(x)}</option>`).join("")}</select><select id="dif"><option value="">Toutes les difficultés</option>${["Easy","Medium","Hard"].map(x=>`<option value="${x}">${difficultyLabel(x)}</option>`).join("")}</select></div>`;
function bindChallenges(c,eventId){c.querySelectorAll("[data-ch]").forEach(b=>b.onclick=()=>challenge(b.dataset.ch,eventId));let s=c.querySelector("#search"),ca=c.querySelector("#cat"),di=c.querySelector("#dif");if(s)[s,ca,di].forEach(x=>x.addEventListener(x===s?"input":"change",()=>c.querySelectorAll("[data-card]").forEach(k=>k.style.display=(!s.value||k.dataset.title.includes(s.value.toLowerCase()))&&(!ca.value||k.dataset.cat===ca.value)&&(!di.value||k.dataset.dif===di.value)?"":"none")))}
async function training(c){let ch=await challengeList();cache.challenges=ch;c.innerHTML=`<section class="hero"><h1>⚑ Arène d’entraînement</h1><p>Défis pratiques, indices avec pénalité, points dynamiques et fichiers associés.</p></section>${filt()}<div class="grid cols3">${ch.map(x=>`<div class="card challenge-card" data-card data-title="${esc(x.title.toLowerCase())}" data-cat="${esc(x.category)}" data-dif="${esc(x.difficulty)}"><div class="actions"><span class="badge">${esc(categoryLabel(x.category))}</span>${x.dynamic_enabled?'<span class="badge cyan">Dynamique</span>':""}</div><h3>${x.solved?"✅ ":""}${esc(x.title)}</h3><p>${esc(x.description)}</p><div class="between"><strong>${x.base_points} pts</strong><button class="btn primary" data-ch="${x.id}">Ouvrir</button></div></div>`).join("")}</div>`;bindChallenges(c,null)}
async function challenge(id,eventId){
  let [{data:x},{data:files},{data:h},{data:w},{data:s}]=await Promise.all([sb.from("challenges").select("*").eq("id",id).single(),sb.from("challenge_files").select("*").eq("challenge_id",id),sb.from("hint_usage").select("*").eq("user_id",me.id).eq("challenge_id",id),sb.from("writeups").select("*").eq("challenge_id",id).maybeSingle(),eventId?sb.from("solves").select("*").eq("challenge_id",id).eq("event_id",eventId).eq("user_id",me.id).maybeSingle():sb.from("solves").select("*").eq("challenge_id",id).is("event_id",null).eq("user_id",me.id).maybeSingle()]),hu=(h||[]).find(z=>(z.event_id||null)===(eventId||null)),d=document.createElement("div"),lab=safeHttpUrl(x?.lab_url);
  d.className="modalbg";d.innerHTML=`<div class="modal"><div class="modal-head"><h2>${esc(x.title)}</h2><button id="x">✕</button></div><p>${esc(x.description)}</p><div class="actions"><span class="badge">${esc(categoryLabel(x.category))}</span><strong>${x.base_points} pts</strong>${s?`<span class="badge green">✅ ${s.points} pts</span>`:""}</div>${appState.ai_enabled?`<p><button class="btn secondary" id="askAiChallenge">🤖 Demander un indice à l’IA</button></p>`:""}${lab?`<p><a class="btn warning" href="${esc(lab)}" target="_blank" rel="noopener noreferrer">🧪 Ouvrir le laboratoire</a></p>`:""}<div id="files" class="actions mt"></div><div class="panel mt"><h3>💡 Indice</h3>${hu?`<p>${esc(x.hint||"")}</p><span class="badge yellow">-${hu.penalty} pts</span>`:`<button class="btn warning" id="hint">Débloquer</button>`}</div><form id="ff" class="form mt"><input name="flag" maxlength="512" autocomplete="off" required placeholder="${esc(appState.flag_format||"CYBERCLUB{...}")}"><button class="btn primary">Soumettre</button></form>${w&&s?`<div class="panel mt"><h3>📝 ${esc(w.title)}</h3><p>${esc(w.content)}</p></div>`:""}</div>`;
  document.body.appendChild(d);d.querySelector("#x").onclick=()=>d.remove();if(appState.ai_enabled){let ab=d.querySelector("#askAiChallenge");if(ab)ab.onclick=()=>showAiModal({page:eventId?"ctf":"training",event_id:eventId||null,challenge:{title:x.title,category:categoryLabel(x.category),difficulty:difficultyLabel(x.difficulty),description:x.description,hint:hu?x.hint:null}})};
  if(files?.length)d.querySelector("#files").innerHTML=files.map(f=>`<button class="btn secondary" data-file="${esc(f.storage_path)}" data-name="${esc(f.original_name)}">⬇ ${esc(f.original_name)}</button>`).join("");
  d.querySelectorAll("[data-file]").forEach(b=>b.onclick=()=>download(b.dataset.file,b.dataset.name));
  if(!hu)d.querySelector("#hint").onclick=async()=>{let {data,error}=await sb.rpc("use_hint",{p_challenge:id,p_event:eventId});if(error)toast("❌ "+errFr(error));else{toast(`💡 -${data.penalty} pts`);d.remove();challenge(id,eventId)}};
  ff.onsubmit=async e=>{e.preventDefault();let {data,error}=await sb.rpc("submit_flag",{p_challenge:id,p_flag:new FormData(e.target).get("flag"),p_event:eventId});if(error)toast("❌ "+errFr(error));else if(!data.ok)toast("❌ Drapeau incorrect");else{toast(data.new_solve?`✅ +${data.points} pts${data.first_blood?" • Première résolution 🩸":""}`:"Déjà résolu");d.remove();await refreshMe();go(eventId?"ctf":"training")}};
}
async function download(path,name){let {data,error}=await sb.storage.from("challenge-files").download(path);if(error)return toast("❌ "+errFr(error));let u=URL.createObjectURL(data),a=document.createElement("a");a.href=u;a.download=name;a.click();URL.revokeObjectURL(u)}

async function teams(c){
  let [{data:mine,error:mineError},{data:all}]=await Promise.all([sb.rpc("get_my_team"),sb.rpc("list_teams")]);
  if(mineError)throw mineError;
  if(mine){
    let isCaptain=Boolean(mine.is_captain||mine.team?.captain_id===me.id);
    c.innerHTML=`<section class="hero"><div class="between"><div><h1>👥 ${esc(mine.team.name)}</h1><p>${esc(mine.team.description||"")}</p></div>${isCaptain?'<span class="badge purple">CAPITAINE</span>':""}</div><div class="team-code-box mt"><div><small class="muted">Code d’invitation de l’équipe</small><code>${esc(mine.team.join_code)}</code></div><button class="btn primary" id="copyTeamCode">📋 Copier le code</button></div></section>
    <div class="card"><div class="between"><h2>Membres</h2><span class="badge">${(mine.members||[]).length} membre(s)</span></div>${(mine.members||[]).map(x=>`<div class="lesson between"><span><strong>@${esc(x.username)}</strong>${x.is_captain?' <span class="badge purple">Capitaine</span>':""}<br><small class="muted">${esc(x.name)}</small></span><span class="actions"><span>${x.xp} XP • Niv. ${x.level}</span>${isCaptain&&!x.is_captain?`<button class="btn danger" data-remove-member="${x.id}">Retirer</button>`:""}</span></div>`).join("")}</div>
    ${isCaptain?`<div class="card mt"><h2>➕ Ajouter un membre</h2><p class="muted">Recherche un membre actif par pseudo ou nom. Il doit ne faire partie d’aucune autre équipe.</p><form id="memberSearch" class="form"><div class="two"><input name="q" maxlength="60" placeholder="Pseudo ou nom"><button class="btn secondary">Rechercher</button></div></form><div id="teamCandidates" class="mt"></div></div>`:""}
    <button class="btn danger mt" id="leave">Quitter l’équipe</button>`;

    copyTeamCode.onclick=async()=>toast(await copyText(mine.team.join_code)?"✅ Code d’équipe copié":"❌ Impossible de copier le code");
    leave.onclick=async()=>{if(!confirm(isCaptain?"Quitter/supprimer l’équipe ? Si d’autres membres sont présents, le capitaine ne peut pas quitter.":"Quitter cette équipe ?"))return;let {error}=await sb.rpc("leave_team");if(error)toast("❌ "+errFr(error));else teams(c)};

    if(isCaptain){
      const box=c.querySelector("#teamCandidates");
      const renderCandidates=async(q="")=>{
        box.innerHTML='<div class="muted">Recherche…</div>';
        let {data,error}=await sb.rpc("list_team_candidates",{p_query:q});
        if(error){box.innerHTML=`<div class="notice">❌ ${esc(errFr(error))}</div>`;return}
        box.innerHTML=(data||[]).length?(data||[]).map(x=>`<div class="lesson between"><span><strong>@${esc(x.username)}</strong><br><small class="muted">${esc(x.name)} • ${x.xp} XP • Niv. ${x.level}</small></span><button class="btn primary" data-add-member="${x.id}">Ajouter</button></div>`).join(""):empty("Aucun membre disponible.");
        box.querySelectorAll("[data-add-member]").forEach(b=>b.onclick=async()=>{b.disabled=true;let {error}=await sb.rpc("captain_add_team_member",{p_user:b.dataset.addMember});toast(error?"❌ "+errFr(error):"✅ Membre ajouté à l’équipe");if(!error)teams(c);else b.disabled=false});
      };
      await renderCandidates("");
      memberSearch.onsubmit=e=>{e.preventDefault();renderCandidates(new FormData(e.target).get("q")||"")};
      c.querySelectorAll("[data-remove-member]").forEach(b=>b.onclick=async()=>{if(!confirm("Retirer ce membre de l’équipe ?"))return;let {error}=await sb.rpc("captain_remove_team_member",{p_user:b.dataset.removeMember});toast(error?"❌ "+errFr(error):"✅ Membre retiré");if(!error)teams(c)});
    }
  }else{
    c.innerHTML=`<section class="hero"><h1>👥 Équipes</h1></section><div class="grid cols2"><form id="ct" class="card form"><h2>Créer</h2><input name="name" minlength="2" maxlength="60" required placeholder="Nom équipe"><textarea name="description" maxlength="500" placeholder="Description"></textarea><button class="btn primary">Créer</button></form><form id="jt" class="card form"><h2>Rejoindre</h2><input name="code" maxlength="32" autocomplete="off" required placeholder="Code équipe"><button class="btn secondary">Rejoindre</button></form></div><div class="card mt">${(all||[]).map(x=>`<div class="lesson"><strong>${esc(x.name)}</strong><p>${esc(x.description||"")}</p></div>`).join("")||empty("Aucune équipe.")}</div>`;
    ct.onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),{data,error}=await sb.rpc("create_team",{p_name:f.get("name"),p_description:f.get("description")});if(error)toast("❌ "+errFr(error));else{toast("✅ Équipe créée");teams(c)}};
    jt.onsubmit=async e=>{e.preventDefault();let {error}=await sb.rpc("join_team",{p_code:new FormData(e.target).get("code")});if(error)toast("❌ "+errFr(error));else teams(c)}
  }
}

async function ctf(c){
  let [{data:e},{data:r}]=await Promise.all([sb.from("ctf_events").select("*,seasons(title)").order("starts_at",{ascending:false}),sb.from("ctf_registrations").select("event_id").eq("user_id",me.id)]);cache.events=e||[];let set=new Set((r||[]).map(x=>x.event_id));
  c.innerHTML=`<section class="hero"><h1>🚩 CTF hebdomadaires</h1></section><div class="grid cols2">${(e||[]).map(x=>{let ended=Date.now()>new Date(x.ends_at).getTime(),canReg=!set.has(x.id)&&!ended;return `<div class="card"><div class="between"><h2>${esc(x.title)}</h2><span class="badge ${x.is_open?"green":"red"}">${x.is_open?"OUVERT":ended?"TERMINÉ":"FERMÉ"}</span></div><p>${esc(x.description||"")}</p><small class="muted">${fmt(x.starts_at)} → ${fmt(x.ends_at)} • ${esc(x.seasons?.title||"Sans saison")}</small><div class="actions mt">${set.has(x.id)?'<span class="badge cyan">✅ Inscrit</span>':canReg?`<button class="btn primary" data-reg="${x.id}">S'inscrire</button>`:""}<button class="btn secondary" data-event="${x.id}">Voir</button></div></div>`}).join("")}</div>`;
  c.querySelectorAll("[data-reg]").forEach(b=>b.onclick=async()=>{let {error}=await sb.rpc("register_ctf",{p_event:b.dataset.reg});if(error)toast("❌ "+errFr(error));else ctf(c)});c.querySelectorAll("[data-event]").forEach(b=>b.onclick=()=>openEvent(b.dataset.event));
}
async function openEvent(id){
  let e=cache.events.find(x=>x.id===id)||(await sb.from("ctf_events").select("*").eq("id",id).single()).data;
  let c=document.getElementById("content");
  if(!e){c.innerHTML=empty("CTF introuvable.");return}
  const now=Date.now(),start=new Date(e.starts_at).getTime(),end=new Date(e.ends_at).getTime();
  const live=Boolean(e.is_open)&&now>=start&&now<=end;
  const canPreview=me?.role==="admin"||me?.role==="trainer"||(me?.role==="organizer"&&e.created_by===me.id);
  if(!live&&!canPreview){
    const ended=Number.isFinite(end)&&now>end;
    const title=ended?"Cette compétition est terminée":"La compétition n’est pas encore ouverte";
    const text=ended?"Les défis ne sont plus accessibles depuis la page de compétition. Consulte les Archives CTF lorsqu’elles sont disponibles.":"Les défis seront révélés uniquement lorsque l’organisateur ouvrira officiellement le CTF et que l’heure de début sera atteinte.";
    c.innerHTML=`<button class="btn ghost" id="back">← CTF</button><section class="hero mt"><span class="badge ${ended?"red":"yellow"}">${ended?"TERMINÉ":"EN ATTENTE"}</span><h1>${esc(e.title)}</h1><p>${esc(e.description||"")}</p></section><div class="card"><h2>${title}</h2><p>${text}</p><small class="muted">${fmt(e.starts_at)} → ${fmt(e.ends_at)}</small></div>`;
    c.querySelector("#back").onclick=()=>go("ctf");
    return;
  }
  let ch=await challengeList(id);
  const preview=!live&&canPreview;
  c.innerHTML=`<button class="btn ghost" id="back">← CTF</button><section class="hero mt"><div class="between"><div><h1>${esc(e.title)}</h1><p>${esc(e.description||"")}</p></div>${preview?'<span class="badge yellow">APERÇU ORGANISATION</span>':'<span class="badge green">OUVERT</span>'}</div></section>${preview?'<div class="notice"><strong>Aperçu privé</strong><p>Ces défis sont visibles pour toi parce que tu gères ou supervises le CTF. Les membres ne les verront qu’après l’ouverture officielle.</p></div>':""}${filt()}<div class="grid cols3">${ch.map(x=>`<div class="card challenge-card" data-card data-title="${esc(x.title.toLowerCase())}" data-cat="${esc(x.category)}" data-dif="${esc(x.difficulty)}"><span class="badge">${esc(categoryLabel(x.category))}</span><h3>${x.solved?"✅ ":""}${esc(x.title)}</h3><p>${esc(x.description)}</p><button class="btn primary" data-ch="${x.id}">Ouvrir</button></div>`).join("")||empty("Aucun défi dans ce CTF.")}</div>`;
  c.querySelector("#back").onclick=()=>go("ctf");
  bindChallenges(c,id)
}

async function archives(c){
  let {data,error}=await sb.rpc("get_ctf_archives");
  if(error)throw error;
  let rows=data||[];
  c.innerHTML=`<section class="hero"><h1>🗂 Archives CTF</h1><p>Retrouve les compétitions terminées, leur classement final, les défis et les premières résolutions.</p></section>
  <div class="grid cols2">${rows.map(x=>`<div class="card"><div class="between"><div><span class="badge red">TERMINÉ</span><h2>${esc(x.title)}</h2></div><span class="badge">${esc(x.season_title||"Sans saison")}</span></div><p>${esc(x.description||"")}</p><small class="muted">${fmt(x.starts_at)} → ${fmt(x.ends_at)}</small><div class="grid cols4 mt">${stat("🚩","Défis",x.challenge_count)}${stat("👥","Participants",x.participant_count)}${stat("✅","Résolutions",x.solve_count)}${stat("🏆","Vainqueur",x.leaderboard_visible&&x.winner_username?"@"+x.winner_username:"—")}</div>${!x.leaderboard_visible?'<div class="notice mt"><strong>Classement masqué</strong><p>Le Formateur ou l’Admin a retiré ce classement de l’affichage public.</p></div>':""}<button class="btn primary mt" data-archive="${x.event_id}">Voir l’archive</button></div>`).join("")||empty("Aucun CTF archivé pour le moment.")}</div>`;
  c.querySelectorAll("[data-archive]").forEach(b=>b.onclick=()=>openArchive(b.dataset.archive));
}

async function openArchive(id){
  let {data,error}=await sb.rpc("get_ctf_archive",{p_event:id});
  if(error)return toast("❌ "+errFr(error));
  let c=document.getElementById("content"),ev=data?.event||{},st=data?.stats||{},lb=data?.leaderboard||[],ch=data?.challenges||[],top=lb.slice(0,3);
  const podium=top.length?`<div class="grid cols3 mt">${top.map((x,i)=>`<div class="card"><span class="badge ${i===0?"yellow":i===1?"cyan":"purple"}">${i===0?"1er":i===1?"2e":"3e"}</span><h2>@${esc(x.username)}</h2><p><strong>${esc(x.score)} pts</strong> • ${esc(x.solves)} défi(s)</p></div>`).join("")}</div>`:"";
  const ranking=ev.leaderboard_visible?table("Classement final",["#","Pseudo","Résolus","Score","XP"],lb.map(x=>[x.rank,"@"+x.username,x.solves,x.score,x.xp])):`<div class="card mt"><h2>Classement final</h2><p>Ce classement a été masqué manuellement par le Formateur ou l’Admin.</p></div>`;
  c.innerHTML=`<button class="btn ghost" id="backArchives">← Archives CTF</button><section class="hero mt"><div class="between"><div><span class="badge red">ARCHIVE</span><h1>${esc(ev.title||"CTF")}</h1><p>${esc(ev.description||"")}</p></div><span class="badge">${esc(ev.season_title||"Sans saison")}</span></div><small class="muted">${fmt(ev.starts_at)} → ${fmt(ev.ends_at)}</small></section><div class="grid cols4">${stat("🚩","Défis",st.challenges||0)}${stat("👥","Participants",st.participants||0)}${stat("✅","Résolutions",st.solves||0)}${stat("🩸","Défis résolus",st.first_solves||0)}</div>${podium}${ranking}<div class="card mt"><h2>Défis de la compétition</h2>${ch.map(x=>`<div class="lesson between"><div><span class="badge">${esc(categoryLabel(x.category))}</span> <span class="badge">${esc(difficultyLabel(x.difficulty))}</span><strong> ${esc(x.title)}</strong><br><small class="muted">${esc(x.solves)} résolution(s)${x.first_username?` • Première résolution : @${esc(x.first_username)} — ${fmt(x.first_solved_at)}`:" • Aucune résolution"}</small></div><span class="actions">${x.writeup_available?`<button class="btn secondary" data-archive-writeup="${x.id}">Voir le Write-up</button>`:'<span class="badge">Write-up verrouillé</span>'}</span></div>`).join("")||empty("Aucun défi dans cette archive.")}</div>`;
  c.querySelector("#backArchives").onclick=()=>go("archives");
  c.querySelectorAll("[data-archive-writeup]").forEach(b=>b.onclick=()=>archiveWriteup(b.dataset.archiveWriteup));
}

async function archiveWriteup(challengeId){
  let {data,error}=await sb.from("writeups").select("title,content,challenges(title,category)").eq("challenge_id",challengeId).maybeSingle();
  if(error||!data)return toast("❌ Write-up indisponible ou encore verrouillé.");
  let d=document.createElement("div");d.className="modalbg";d.innerHTML=`<div class="modal"><div class="modal-head"><div><span class="badge">${esc(categoryLabel(data.challenges?.category||""))}</span><h2>${esc(data.title||data.challenges?.title||"Write-up")}</h2></div><button id="x">✕</button></div><div class="panel mt"><p>${esc(data.content||"")}</p></div></div>`;document.body.appendChild(d);d.querySelector("#x").onclick=()=>d.remove();d.onclick=e=>{if(e.target===d)d.remove()};
}


async function calendar(c){
  const now=new Date(),from=new Date(now.getTime()-30*24*60*60*1000),to=new Date(now.getTime()+180*24*60*60*1000);
  let {data:events,error}=await sb.rpc("get_calendar_events",{p_from:from.toISOString(),p_to:to.toISOString()});
  if(error)throw error;
  events=(events||[]).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));
  const upcoming=events.filter(x=>new Date(x.ends_at||x.starts_at).getTime()>Date.now());
  const recent=events.filter(x=>new Date(x.ends_at||x.starts_at).getTime()<=Date.now()).reverse().slice(0,15);
  const canManage=["trainer","admin"].includes(me.role);
  const renderItem=x=>`<div class="calendar-item"><div class="calendar-date"><strong>${new Date(x.starts_at).toLocaleDateString("fr-FR",{day:"2-digit",month:"short"})}</strong><small>${new Date(x.starts_at).toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"})}</small></div><div class="calendar-body"><div class="actions"><span class="badge ${x.event_type==="CTF"?"red":"cyan"}">${esc(calendarTypeLabel(x.event_type))}</span>${x.is_open?'<span class="badge green">EN COURS</span>':""}</div><h3>${esc(x.title)}</h3><p>${esc(x.description||"")}</p><small class="muted">${fmt(x.starts_at)} → ${fmt(x.ends_at)}${x.location?` • ${esc(x.location)}`:""}</small>${new Date(x.ends_at||x.starts_at).getTime()>Date.now()?`<div class="countdown-inline" data-countdown data-start="${esc(x.starts_at)}" data-end="${esc(x.ends_at||"")}"></div>`:""}</div><div class="calendar-actions">${x.source==="CTF"?`<button class="btn secondary" data-calendar-ctf="${x.event_id}">Voir le CTF</button>`:(canManage&&x.can_manage?`<button class="btn ghost" data-calendar-edit="${x.event_id}">Modifier</button><button class="btn danger" data-calendar-delete="${x.event_id}">Supprimer</button>`:"")}</div></div>`;
  const manage=canManage?`<form id="calendarForm" class="card form mt"><div class="between"><div><h2>Ajouter un événement du club</h2><p class="muted">Les CTF créés par l’Organisateur apparaissent automatiquement dans le calendrier.</p></div><button type="button" class="btn ghost" id="calendarReset" hidden>Annuler la modification</button></div><input type="hidden" name="id"><div class="two"><select name="event_type"><option value="TRAINING">Formation</option><option value="WORKSHOP">Atelier</option><option value="MEETING">Réunion</option><option value="OTHER">Autre</option></select><input name="title" maxlength="150" required placeholder="Titre de l'événement"></div><textarea name="description" maxlength="3000" placeholder="Description"></textarea><div class="two"><div><label>Début</label><input name="start" type="datetime-local" required></div><div><label>Fin</label><input name="end" type="datetime-local" required></div></div><input name="location" maxlength="200" placeholder="Lieu ou lien (facultatif)"><button class="btn primary">Enregistrer l'événement</button></form>`:"";
  c.innerHTML=`<section class="hero"><h1>📅 Calendrier du Cyber Club</h1><p>CTF hebdomadaires, formations, ateliers et réunions du club.</p></section>${upcoming[0]?`<div class="card countdown-card"><span class="badge purple">PROCHAIN ÉVÉNEMENT</span><h2>${esc(upcoming[0].title)}</h2><div class="countdown-big" data-countdown data-start="${esc(upcoming[0].starts_at)}" data-end="${esc(upcoming[0].ends_at||"")}"></div><small class="muted">${fmt(upcoming[0].starts_at)}${upcoming[0].location?` • ${esc(upcoming[0].location)}`:""}</small></div>`:""}<div class="card mt"><h2>À venir</h2><div class="calendar-list">${upcoming.map(renderItem).join("")||empty("Aucun événement à venir.")}</div></div>${manage}<div class="card mt"><h2>Événements récents</h2><div class="calendar-list">${recent.map(renderItem).join("")||empty("Aucun événement récent.")}</div></div>`;
  bindCountdowns(c);
  c.querySelectorAll("[data-calendar-ctf]").forEach(b=>b.onclick=()=>openEvent(b.dataset.calendarCtf));
  if(canManage){
    const form=c.querySelector("#calendarForm"),reset=c.querySelector("#calendarReset");
    const clearForm=()=>{form.reset();form.elements.id.value="";reset.hidden=true;form.querySelector('button[type="submit"]').textContent="Enregistrer l'événement"};
    reset.onclick=clearForm;
    form.onsubmit=async e=>{e.preventDefault();let f=new FormData(form),start=new Date(f.get("start")),end=new Date(f.get("end"));if(!Number.isFinite(start.getTime())||!Number.isFinite(end.getTime())||end<=start)return toast("❌ La date de fin doit être après le début.");let {error}=await sb.rpc("save_calendar_event",{p_id:f.get("id")||null,p_title:f.get("title"),p_description:f.get("description"),p_event_type:f.get("event_type"),p_start:start.toISOString(),p_end:end.toISOString(),p_location:f.get("location")});toast(error?"❌ "+errFr(error):"✅ Événement enregistré");if(!error)calendar(c)};
    c.querySelectorAll("[data-calendar-edit]").forEach(b=>b.onclick=()=>{let x=events.find(z=>z.event_id===b.dataset.calendarEdit&&z.source==="CLUB");if(!x)return;form.elements.id.value=x.event_id;form.elements.event_type.value=x.event_type;form.elements.title.value=x.title||"";form.elements.description.value=x.description||"";form.elements.location.value=x.location||"";const local=v=>{let d=new Date(v),off=d.getTimezoneOffset();return new Date(d.getTime()-off*60000).toISOString().slice(0,16)};form.elements.start.value=local(x.starts_at);form.elements.end.value=local(x.ends_at);reset.hidden=false;form.querySelector('button[type="submit"]').textContent="Enregistrer les modifications";form.scrollIntoView({behavior:"smooth",block:"center"})});
    c.querySelectorAll("[data-calendar-delete]").forEach(b=>b.onclick=async()=>{if(!confirm("Supprimer cet événement du calendrier ?"))return;let {error}=await sb.rpc("delete_calendar_event",{p_id:b.dataset.calendarDelete});toast(error?"❌ "+errFr(error):"✅ Événement supprimé");if(!error)calendar(c)});
  }
}

