async function refreshUnreadCount(){
  if(!sb||!me?.id)return;
  let {data,error}=await sb.rpc("get_notification_summary");if(error)return;
  let btn=document.querySelector('[data-r="notifications"]');if(!btn)return;
  btn.querySelector(".notif-counter")?.remove();let n=Number(data?.unread||0);if(n>0){let sp=document.createElement("span");sp.className="notif-counter";sp.textContent=n>99?"99+":String(n);btn.appendChild(sp)}
}
const notifCategoryLabel=v=>({CTF:"CTF",BADGE:"Badge",CALENDAR:"Calendrier",ACCOUNT:"Compte",ANNOUNCEMENT:"Annonce",SYSTEM:"Système"}[v]||"Système");
async function notifications(c){
  ensureNotificationStyles();
  let mode="all";
  async function render(){
    let q=sb.from("notifications").select("id,title,body,is_read,created_at,category,action_route,meta").eq("user_id",me.id).order("created_at",{ascending:false}).limit(250);
    if(mode==="unread")q=q.eq("is_read",false);
    let {data,error}=await q;if(error){c.innerHTML=`<div class="card"><h2>Notifications indisponibles</h2><p>${esc(errFr(error))}</p></div>`;return}
    let rows=data||[];
    c.innerHTML=`<section class="hero"><h1>🔔 Notifications</h1><p>Retrouve les alertes du club, des CTF, des badges et du calendrier.</p></section>
    <div class="card"><div class="notif-toolbar"><div class="notif-filters"><button class="btn ${mode==="all"?"primary":"ghost"}" id="nfAll">Toutes</button><button class="btn ${mode==="unread"?"primary":"ghost"}" id="nfUnread">Non lues</button></div><div class="actions"><button class="btn secondary" id="nfReadAll">Tout marquer comme lu</button><button class="btn ghost" id="nfClear">Supprimer les lues</button></div></div>
    <div id="notifList">${rows.length?rows.map(x=>`<div class="notif-item ${x.is_read?"":"unread"}" data-nid="${esc(x.id)}"><div class="notif-head"><div><div class="notif-title"><strong>${esc(x.title)}</strong><span class="badge notif-category">${esc(notifCategoryLabel(x.category))}</span>${x.is_read?"":'<span class="badge cyan">Nouveau</span>'}</div><p>${esc(x.body)}</p><small class="muted">${fmt(x.created_at)}</small></div></div><div class="notif-actions">${!x.is_read?`<button class="btn ghost n-read" data-id="${esc(x.id)}">Marquer comme lue</button>`:""}${x.action_route&&routeLabels[x.action_route]?`<button class="btn secondary n-open" data-route="${esc(x.action_route)}" data-id="${esc(x.id)}">Ouvrir</button>`:""}<button class="btn ghost n-del" data-id="${esc(x.id)}">Supprimer</button></div></div>`).join(""):empty(mode==="unread"?"Aucune notification non lue.":"Aucune notification.")}</div></div>`;
    nfAll.onclick=()=>{mode="all";render()};nfUnread.onclick=()=>{mode="unread";render()};
    nfReadAll.onclick=async()=>{let {error}=await sb.rpc("mark_all_notifications_read");if(error)return toast("❌ "+errFr(error));toast("Toutes les notifications sont lues.");await refreshUnreadCount();render()};
    nfClear.onclick=async()=>{if(!confirm("Supprimer toutes les notifications déjà lues ?"))return;let {error}=await sb.rpc("clear_read_notifications");if(error)return toast("❌ "+errFr(error));toast("Notifications lues supprimées.");await refreshUnreadCount();render()};
    c.querySelectorAll(".n-read").forEach(b=>b.onclick=async()=>{let {error}=await sb.rpc("mark_notification_read",{p_id:b.dataset.id});if(error)return toast("❌ "+errFr(error));await refreshUnreadCount();render()});
    c.querySelectorAll(".n-del").forEach(b=>b.onclick=async()=>{let {error}=await sb.rpc("delete_notification",{p_id:b.dataset.id});if(error)return toast("❌ "+errFr(error));await refreshUnreadCount();render()});
    c.querySelectorAll(".n-open").forEach(b=>b.onclick=async()=>{await sb.rpc("mark_notification_read",{p_id:b.dataset.id});await refreshUnreadCount();go(b.dataset.route)});
  }
  await render();
}
