async function statistics(c){
  ensureStatsStyles();
  let {data,error}=await sb.rpc("get_my_statistics");
  if(error){c.innerHTML=`<div class="card"><h2>Statistiques indisponibles</h2><p>${esc(errFr(error))}</p></div>`;return}
  let d=data||{},s=d.summary||{},cats=d.categories||[],weeks=d.weekly_activity||[],courses=d.courses||[],ctfs=d.ctf_history||[];
  let maxCat=Math.max(1,...cats.map(x=>Number(x.solves)||0));
  let catHtml=cats.map(x=>`<div class="stats-bar-row"><strong>${esc(categoryLabel(x.category))}</strong><div class="stats-bar-track"><div class="stats-bar-fill" style="width:${Math.max(4,(Number(x.solves)||0)*100/maxCat)}%"></div></div><span>${esc(x.solves)} défis • ${esc(x.points)} pts</span></div>`).join("")||empty("Aucun défi résolu pour le moment.");
  let maxWeek=Math.max(1,...weeks.map(x=>(Number(x.solves)||0)+(Number(x.lessons)||0)+(Number(x.quizzes)||0)));
  let weekHtml=weeks.map(x=>{let total=(+x.solves||0)+(+x.lessons||0)+(+x.quizzes||0),h=Math.max(2,Math.round(total*120/maxWeek));let date=new Date(x.week_start);let label=date.toLocaleDateString("fr-FR",{day:"2-digit",month:"2-digit"});return `<div class="week-col"><div class="week-stack" title="${esc(`${x.solves} défis, ${x.lessons} leçons, ${x.quizzes} quiz`)}"><div class="week-seg" style="height:${Math.max(2,h*(+x.solves||0)/Math.max(1,total))}px"></div><div class="week-seg lesson" style="height:${Math.max(2,h*(+x.lessons||0)/Math.max(1,total))}px"></div><div class="week-seg quiz" style="height:${Math.max(2,h*(+x.quizzes||0)/Math.max(1,total))}px"></div></div><div class="week-label">${esc(label)}</div></div>`}).join("");
  let courseHtml=courses.map(x=>`<div class="lesson"><div class="between"><strong>${esc(x.title)}</strong><span>${esc(x.completed)}/${esc(x.total)} • ${esc(x.progress)}%</span></div><div class="progress-line"><span style="width:${Math.max(0,Math.min(100,Number(x.progress)||0))}%"></span></div></div>`).join("")||empty("Aucun cours publié.");
  let best=cats[0];
  c.innerHTML=`<section class="hero"><span class="badge cyan">Progression personnelle</span><h1>📊 Mes statistiques</h1><p>Une vue privée de ta progression pédagogique et de tes performances CTF.</p></section>
  <div class="grid cols4">${stat("⭐","XP",s.xp||0)}${stat("🎯","Niveau",s.level||1)}${stat("🚩","Défis résolus",s.solves||0)}${stat("🏅","Badges",s.badges||0)}</div>
  <div class="grid cols4 mt">${stat("📚","Leçons",`${s.lessons_completed||0}/${s.lessons_total||0}`)}${stat("✅","Quiz réussis",`${s.quizzes_passed||0}/${s.quizzes_attempted||0}`)}${stat("🩸","Premiers sangs",s.first_bloods||0)}${stat("🏆","Victoires CTF",s.ctf_wins||0)}</div>
  <div class="grid cols3 mt"><div class="card"><span class="muted">Rang entraînement</span><div class="stats-rank">#${esc(s.training_rank||"—")}</div><small>${esc(s.training_score||0)} points d'entraînement</small></div><div class="card"><span class="muted">Rang XP global</span><div class="stats-rank">#${esc(s.xp_rank||"—")}</div><small>${esc(s.xp||0)} XP</small></div><div class="card"><span class="muted">Meilleure catégorie</span><div class="stat">${best?esc(categoryLabel(best.category)):"—"}</div><small>${best?`${esc(best.solves)} résolutions • ${esc(best.points)} pts`:"Commence un défi pour obtenir une spécialité."}</small></div></div>
  <div class="grid cols2 mt"><div class="card"><h2>Répartition par catégorie</h2><div class="stats-bars mt">${catHtml}</div></div><div class="card"><h2>Activité — 8 dernières semaines</h2><div class="week-chart">${weekHtml}</div><div class="actions"><span class="badge cyan">Défis</span><span class="badge purple">Leçons</span><span class="badge green">Quiz</span></div></div></div>
  <div class="grid cols2 mt"><div class="card"><h2>Progression dans les cours</h2>${courseHtml}</div><div>${table("Historique CTF",["CTF","Rang","Résolutions","Score"],ctfs.map(x=>[x.title,`#${x.rank}/${x.participants}`,x.solves,x.score]))}</div></div>`;
  setCyberBotContext({page:"statistics",statistics:{summary:s,categories:cats.slice(0,8)}});
}

