  c.innerHTML=`<section class="hero profile-hero"><div>${av?`<img class="avatar" src="${esc(av)}" alt="Photo de profil">`:`<div class="avatar avatar-fallback">${esc((me.username||"?").slice(0,2).toUpperCase())}</div>`}</div><div><span class="badge ${rb(me.role)}">${roles[me.role]}</span><h1>@${esc(me.username)}</h1><p>${esc(me.email)}</p></div></section><div class="grid cols4">${stat("⭐","XP",me.xp)}${stat("🎯","Niveau",me.level)}${stat("🚩","Résolutions",s?.length||0)}${stat("📚","Leçons",p?.length||0)}</div><div class="card mt"><div class="between"><div><h2>Badges automatiques</h2><p class="muted">Ils sont attribués automatiquement selon ta progression et tes performances.</p></div><span class="badge cyan">${be?"Mode local":(b||[]).length+" obtenu(s)"}</span></div><div class="mt">${badgeCards||empty("Aucun badge débloqué pour le moment.")}</div></div><form id="pf" class="card form mt"><h2>Modifier mon profil</h2><div class="two"><input name="name" maxlength="80" value="${esc(me.name)}" required><input name="username" minlength="3" maxlength="30" pattern="[A-Za-z0-9_.-]+" value="${esc(me.username)}" required></div><div class="two"><input name="university" maxlength="100" value="${esc(me.university||"")}" placeholder="Université"><input name="study_level" maxlength="50" value="${esc(me.study_level||"")}" placeholder="Niveau"></div><label>Photo de profil (JPG/PNG/WEBP, 5 Mo max.)</label><input name="avatar" type="file" accept="image/jpeg,image/png,image/webp"><button class="btn primary">Enregistrer le profil</button></form><form id="pw" class="card form mt"><h2>Changer le mot de passe</h2><input name="p" type="password" minlength="12" autocomplete="new-password" placeholder="12 caractères minimum" required><input name="p2" type="password" minlength="12" autocomplete="new-password" placeholder="Confirmer" required><button class="btn secondary">Modifier</button></form>`;
  pf.onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),file=f.get("avatar"),newPath=me.avatar_path||null,oldPath=me.avatar_path||null;
    if(file?.size){if(file.size>5*1024*1024)return toast("❌ Photo trop grande (5 Mo max.)");if(!["image/jpeg","image/png","image/webp"].includes(file.type))return toast("❌ Format photo non autorisé");let ext=file.type==="image/png"?"png":file.type==="image/webp"?"webp":"jpg";newPath=`${me.id}/avatar-${Date.now()}.${ext}`;let up=await sb.storage.from("avatars").upload(newPath,file,{upsert:false,contentType:file.type});if(up.error)return toast("❌ "+errFr(up.error))}
    let {data,error}=await sb.rpc("update_my_profile",{p_name:f.get("name"),p_username:f.get("username"),p_university:f.get("university"),p_study_level:f.get("study_level"),p_avatar_path:newPath});if(error){if(newPath&&newPath!==oldPath)await sb.storage.from("avatars").remove([newPath]);return toast("❌ "+errFr(error))}if(oldPath&&newPath!==oldPath)await sb.storage.from("avatars").remove([oldPath]);me=data||me;toast("✅ Profil modifié");await refreshMe();shell();go("profile")};
